  sqlgen::PrimaryKey<int> item_id;
  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // Handle connection error
    return {};
  }

  auto conn = *conn_result;

  // 2. Create tables if they don't exist
  auto create_tables_result = conn
    | sqlgen::create_table<Customer>.if_not_exists(true)
    | sqlgen::create_table<Product>.if_not_exists(true)
    | sqlgen::create_table<Order>.if_not_exists(true)
    | sqlgen::create_table<OrderItem>.if_not_exists(true);

  if (!create_tables_result) {
    // Handle table creation error
    return {};
  }

  // 3. Query the database to retrieve all products purchased by a specific customer
  auto query_result = sqlgen::select_from<Customer>(Product::name, Order::order_date, OrderItem::quantity)
    | sqlgen::inner_join<Order, "o">(Customer::customer_id == Order::customer_id)
    | sqlgen::inner_join<OrderItem, "oi">(Order::order_id == OrderItem::order_id)
    | sqlgen::inner_join<Product, "p">(OrderItem::product_id == Product::product_id)
    | sqlgen::where(Customer::customer_id == customer_id)
    | sqlgen::order_by(Order::order_date.desc())
    | sqlgen::to<std::vector<PurchaseHistory>>();

  auto result = create_tables_result | query_result;

  if (!result) {
    // Handle query error
    return {};
  }

  // 4. Return the results as a vector of PurchaseHistory
  return std::move(*result);
}

}  // namespace query_customer_purchase_history
