Here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_employee_hierarchy {

struct Employee {
  sqlgen::PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

std::vector<EmployeeManager> query_employee_hierarchy() {
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        // Return empty vector if connection fails
        return {};
    }

    // Define columns for the self-join
    const auto e1_name = "name"_t1;
    const auto e2_name = "name"_t2;
    const auto e1_manager_id = "manager_id"_t1;
    const auto e2_emp_id = "emp_id"_t2;

    try {
        // Perform the self-join query
        auto result = sqlgen::select_from<Employee, "e1">(e1_name | sqlgen::as<"employee">, 
                                                          e2_name | sqlgen::as<"manager">)
                     | sqlgen::left_join<Employee, "e2">(e1_manager_id == e2_emp_id)
                     | sqlgen::to<std::vector<EmployeeManager>>(conn_result);

        if (result) {
            return std::move(*result);
        } else {
            // Return empty vector if query fails
            return {};
        }
    } catch (...) {
        // Return empty vector on any exception
        return {};
    }
}

}  // namespace query_employee_hierarchy
```

This implementation:

1. **Connects to the database** using `sqlgen::sqlite::connect("test_db.sqlite")`
2. **Defines table aliases** using the literals namespace: `"e1"` for employees and `"e2"` for managers
3. **Performs a LEFT JOIN** between the Employee table (aliased as "e1") and itself (aliased as "e2") on the condition `e1.manager_id = e2.emp_id`
4. **Selects the appropriate columns**: `e1.name` as "employee" and `e2.name` as "manager"
5. **Handles errors gracefully** by returning empty vectors if the connection or query fails
6. **Uses the `to<>` template** to convert the result directly to `std::vector<EmployeeManager>`

The key aspects of the sqlgen library usage:
- `select_from<Employee, "e1">` - selects from the Employee table with alias "e1"
- `left_join<Employee, "e2">` - performs a LEFT JOIN with the same table using alias "e2"
- Column aliasing with `| sqlgen::as<"alias_name">` to match the EmployeeManager struct fields
- The join condition `e1_manager_id == e2_emp_id` creates the self-join relationship

This implementation correctly handles top-level employees (those with null manager_id) through the LEFT JOIN, which will return null/empty optional for their manager names.

