  friend auto operator|(const Read& _r, const Limit& _limit) {
    static_assert(std::is_same_v<LimitType, Nothing>,
                  "You cannot call limit(...) twice.");
    return Read<Type, WhereType, OrderByType, Limit>{.where_ = _r.where_,
                                                     .limit_ = _limit};
  }

  WhereType where_;

  LimitType limit_;
};

