namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    using namespace sqlgen::literals;

    // Connect to the database
    auto connection = sqlgen::sqlite::connect("test_db.sqlite");
    if (!connection) {
        return {}; // Return empty vector if connection fails
    }

    // Start with base query
    auto query = sqlgen::read<std::vector<Book>>;

    // Build conditions dynamically
    std::optional<decltype("title"_c.like(""))> condition;

    // Add title filter if provided
    if (filters.title_keyword) {
        condition = "title"_c.like("%" + *filters.title_keyword + "%");
    }

    // Add min_year filter if provided
    if (filters.min_year) {
        if (condition) {
            condition = *condition && ("year"_c >= *filters.min_year);
        } else {
            condition = "year"_c >= *filters.min_year;
        }
    }

    // Add genre filter if provided
    if (filters.genre) {
        if (condition) {
            condition = *condition && ("genre"_c == *filters.genre);
        } else {
            condition = "genre"_c == *filters.genre;
        }
    }

    // Add max_price filter if provided
    if (filters.max_price) {
        if (condition) {
            condition = *condition && ("price"_c <= *filters.max_price);
        } else {
            condition = "price"_c <= *filters.max_price;
        }
    }

    // Apply WHERE clause if we have any conditions
    if (condition) {
        query = query | sqlgen::where(*condition);
    }

    // Execute the query
    auto result = query(connection);
    if (result) {
        return std::move(*result);
    }

    // Return empty vector on error
    return {};
}

}  // namespace query_search_books_by_criteria
