Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_result.is_ok()) {
    return false; // Failed to connect to database
  }

  auto conn = conn_result.value();

  // SQL statements to add new columns
  std::string add_phone_sql = "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);";
  std::string add_active_sql = "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;";

  // Execute the first ALTER TABLE statement
  auto result1 = sqlgen::exec(conn, add_phone_sql);
  if (!result1.is_ok()) {
    // Check if the error is due to column already existing
    std::string error_msg = result1.error()->what();
    if (error_msg.find("duplicate column name") == std::string::npos &&
        error_msg.find("already exists") == std::string::npos) {
      return false; // Real error, not just column exists
    }
    // If column already exists, continue to next statement
  }

  // Execute the second ALTER TABLE statement
  auto result2 = sqlgen::exec(conn, add_active_sql);
  if (!result2.is_ok()) {
    // Check if the error is due to column already existing
    std::string error_msg = result2.error()->what();
    if (error_msg.find("duplicate column name") == std::string::npos &&
        error_msg.find("already exists") == std::string::npos) {
      return false; // Real error, not just column exists
    }
  }

  return true; // Migration succeeded
}

} // namespace schema_migration_add_column
