  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    if (ids.empty()) {
        return true; // Nothing to delete
    }

    // Connect to the database
    auto conn_result = sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return false; // Connection failed
    }

    auto conn = conn_result.value();

    // Start a transaction for batched updates
    auto trans_result = transaction(conn);
    if (!trans_result) {
        return false; // Transaction start failed
    }

    auto trans = trans_result.value();

    // Build the update query using sqlgen's type-safe API
    // Update the records where doc_id is in the provided list
    auto update_result = update<Document>(
        "is_deleted"_c.set(1),
        "deleted_at"_c.set(sqlgen::DateTime::now())
    ) | where("doc_id"_c.in(ids));

    // Execute the update
    auto exec_result = update_result(trans);
    if (!exec_result) {
        return false; // Update failed
    }

    // Commit the transaction
    auto commit_result = commit(exec_result.value());
    if (!commit_result) {
        return false; // Commit failed
    }

    return true;
}

}  // namespace soft_delete_records
