```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Begin transaction
  auto transaction_result = sqlgen::begin_transaction(conn);
  if (!transaction_result) {
    return false;
  }
  auto transaction = transaction_result.value();

  try {
    // Check if sender has sufficient funds
    auto sender_result = sqlgen::select<Account>()
        | sqlgen::where(sqlgen::col<"account_id"> == from_account_id)
        .one(transaction);

    if (!sender_result || sender_result.value().balance < amount) {
      transaction->rollback();
      return false;
    }

    // Update sender account: deduct amount
    auto update_sender_result = sqlgen::update<Account>(
        sqlgen::col<"balance">.set(sqlgen::col<"balance"> - amount)
    ) | sqlgen::where(sqlgen::col<"account_id"> == from_account_id)(transaction);

    if (!update_sender_result) {
      transaction->rollback();
      return false;
    }

    // Update receiver account: add amount
    auto update_receiver_result = sqlgen::update<Account>(
        sqlgen::col<"balance">.set(sqlgen::col<"balance"> + amount)
    ) | sqlgen::where(sqlgen::col<"account_id"> == to_account_id)(transaction);

    if (!update_receiver_result) {
      transaction->rollback();
      return false;
    }

    // Commit transaction
    auto commit_result = sqlgen::commit(transaction);
    return commit_result.has_value();

  } catch (...) {
    // Rollback if any exception occurs
    transaction->rollback();
    return false;
  }
}

}  // namespace transaction_transfer_funds
```

This implementation:

1. **Connects to the SQLite database** using `sqlgen::sqlite::connect()`
2. **Starts a transaction** using `sqlgen::begin_transaction()`
3. **Checks sufficient funds** by querying the sender's account balance
4. **Updates both accounts** using `sqlgen::update()` with the appropriate SET operations
5. **Uses WHERE clauses** to target the specific accounts
6. **Commits on success** using `sqlgen::commit()`
7. **Rolls back on any failure** using `transaction->rollback()`
8. **Returns true/false** indicating success/failure of the transfer

The code follows the SQLite transaction pattern and uses the `sqlgen` library's type-safe query building features to ensure safety and correctness.

