#pragma once

#include <filesystem>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

#include "eas_common.hpp"

namespace update_eas_table {

void update_eas_table() {
  design_eas_database_with_major();

  // Connect to the database
  auto result = sqlgen::sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // 1. Add a new column `Grade` to the table `Score`, with type `char(1)`, not allowing null values
        return sqlgen::exec(conn, "ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'A';");
      })
      .and_then([](auto&& conn) {
        // 2. Modify the column type of `Age` in the table `Student` to `int`, allowing null values
        // Note: Since SQLite doesn't support direct column type modification, we need to recreate the table
        // First, create a temporary table with the new schema
        return sqlgen::exec(conn, R"(
          CREATE TABLE IF NOT EXISTS Student_temp (
            SNo VARCHAR(10) PRIMARY KEY,
            SName VARCHAR(30),
            Sex INTEGER,
            Birthday DATETIME,
            Major INTEGER,
            Scorses REAL,
            Remark TEXT,
            Age INTEGER
          );
        )");
      })
      .and_then([](auto&& conn) {
        // Copy data from old table to temporary table
        return sqlgen::exec(conn, R"(
          INSERT INTO Student_temp (SNo, SName, Sex, Birthday, Major, Scorses, Remark, Age)
          SELECT SNo, SName, Sex, Birthday, Major, Scorses, Remark, 
                 CASE WHEN Age IS NULL THEN NULL ELSE CAST(Age AS INTEGER) END 
          FROM Student;
        )");
      })
      .and_then([](auto&& conn) {
        // Drop the old table
        return sqlgen::exec(conn, "DROP TABLE Student;");
      })
      .and_then([](auto&& conn) {
        // Rename the temporary table to the original name
        return sqlgen::exec(conn, "ALTER TABLE Student_temp RENAME TO Student;");
      })
      .and_then([](auto&& conn) {
        // 3. Drop the table `Major`
        return sqlgen::drop<Major>(conn);
      });

  if (!result) {
    // Handle error if needed
    throw std::runtime_error("Failed to update EAS table");
  }
}

} // namespace update_eas_table
```

**Explanation of the implementation:**

1. **Adding the `Grade` column to `Score` table:**
   - Used `ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'A'`
   - Added a default value 'A' since the column cannot be NULL

2. **Modifying the `Age` column in `Student` table:**
   - Since SQLite doesn't support direct column type modification, I used a workaround:
     - Created a temporary table `Student_temp` with the desired schema (Age as INTEGER)
     - Copied data from the original table, casting Age to INTEGER
     - Dropped the original table
     - Renamed the temporary table to the original name

3. **Dropping the `Major` table:**
   - Used the `sqlgen::drop<Major>` function provided by the library

The implementation follows SQLite's constraints and uses the available `sqlgen` library functions while handling the specific requirements of the task.

