namespace generate_sql_dry_run {

struct A {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct B {
  sqlgen::PrimaryKey<int> id;
  int a_id;
  double score;
};

/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen::literals;

  // Build a complex query with joins, where, order_by, and limit
  auto query = sqlgen::select_from<A, "a">("a.id"_c, "a.name"_c)
               | sqlgen::inner_join<B, "b">("b.a_id"_c == "a.id"_c)
               | sqlgen::where("b.score"_c > 10.0 && "a.name"_c.like("%x%"))
               | sqlgen::order_by("b.score"_c.desc(), "a.id"_c.asc())
               | sqlgen::limit(10);

  // Generate SQL string for SQLite (dry run)
  std::string sql = sqlgen::sqlite::to_sql(query);

