    throw std::runtime_error("Failed to create table: " + create_table_result.error().what());
  }

  // Clear existing data
  auto clear_result = conn->execute("DELETE FROM Product");
  if (!clear_result) {
    throw std::runtime_error("Failed to clear table: " + clear_result.error().what());
  }

  // Insert products
  for (const auto& product : products) {
    auto insert_result = conn->execute(
      "INSERT INTO Product (product_id, name, price, quantity, discount_rate) VALUES (?, ?, ?, ?, ?)",
      product.product_id, product.name, product.price, product.quantity, product.discount_rate
    );

    if (!insert_result) {
      throw std::runtime_error("Failed to insert product: " + insert_result.error().what());
    }
  }

  // Build and execute the mathematical operations query using sqlgen's type-safe API
