    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = std::move(*conn_result);

  // Create temporary table and insert data
  auto create_result = conn->execute(R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )");

  if (!create_result) {
    throw std::runtime_error("Failed to create table: " + create_result.error().what());
  }

  // Clear any existing data
  conn->execute("DELETE FROM OrderItem").value();

  // Insert the provided items
  auto write_result = write(conn, items);
  if (!write_result) {
    throw std::runtime_error("Failed to write items: " + write_result.error().what());
  }

  // Perform the arithmetic calculations using sqlgen DSL
  auto query = select_from<OrderItem>(
    "item_id"_c,
    "order_id"_c, 
    "product_id"_c,
    "unit_price"_c,
    "quantity"_c,
    "discount_rate"_c.coalesce(0).as("discount_rate"),
    "tax_rate"_c.coalesce(0).as("tax_rate"),
    ("unit_price"_c * "quantity"_c).as("gross_total"),
    (("unit_price"_c * "quantity"_c) * (1 - ("discount_rate"_c.coalesce(0) / 100))).as("discounted_total"),
    ((("unit_price"_c * "quantity"_c) * (1 - ("discount_rate"_c.coalesce(0) / 100))) * (1 + ("tax_rate"_c.coalesce(0) / 100))).as("final_total"),
    (("unit_price"_c * "quantity"_c) / "quantity"_c).as("unit_cost"),
    ("quantity"_c % 10).as("quantity_group"),
    ("unit_price"_c * 0.3).as("estimated_profit")
  );

  // Execute query and return results
  auto result = query.to<std::vector<OrderMetrics>>()(conn);
  if (!result) {
    throw std::runtime_error("Failed to execute query: " + result.error().what());
  }

  return std::move(*result);
}

}  // namespace calculate_order_metrics
