```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace join_orders_customers_payments {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct Payment {
  sqlgen::PrimaryKey<int> payment_id;
  int order_id;
  double amount;
};

struct Consolidated {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Define column references using the sqlgen library
  using namespace sqlgen::literals;

  // Create the query to join the three tables
  auto query = sqlgen::select_from<Order>(
      "order_id"_c, 
      "name"_c | sqlgen::as<"customer_name">, 
      "amount"_c)
    | sqlgen::inner_join<Customer>("customer_id"_c == "customer_id"_c)
    | sqlgen::inner_join<Payment>("order_id"_c == "order_id"_c)
    | sqlgen::order_by("amount"_c.desc())
    | sqlgen::to<std::vector<Consolidated>>();

  // Execute the query and return the results
  return query(conn.value()).value();
}

}  // namespace join_orders_customers_payments
