  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Enable foreign key constraints (required for SQLite)
  auto pragma_result = conn->execute("PRAGMA foreign_keys = ON");
  if (!pragma_result) {
    return false;
  }

  // Create Parent table
  auto parent_table_result = conn | create_table<Parent>{.if_not_exists_ = true};
  if (!parent_table_result) {
    return false;
  }

  // Create Child table with cascade delete
  auto child_table_result = conn | create_table<Child>{.if_not_exists_ = true};
  if (!child_table_result) {
    return false;
  }

  // Insert parent record
  Parent parent{1, "Test Parent"};
  auto insert_parent_result = conn | insert(parent);
  if (!insert_parent_result) {
    return false;
  }

  // Insert child records with the same parent_id
  std::vector<Child> children{
    Child{1, 1, "Child 1"},
    Child{2, 1, "Child 2"},
    Child{3, 1, "Child 3"}
  };

  auto insert_children_result = conn | insert(children);
  if (!insert_children_result) {
    return false;
  }

  // Verify children exist before deletion
  auto count_before_result = conn->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1");
  if (!count_before_result) {
    return false;
  }

  // Delete parent (should cascade to children)
  auto delete_result = conn | delete_from<Parent>{} | where(col<"parent_id"> == 1);
  if (!delete_result) {
    return false;
  }

  // Verify children are automatically deleted
  auto count_after_result = conn->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1");
  if (!count_after_result) {
    return false;
  }

  // Check if cascade deletion worked
  // Before deletion: should have 3 children
  // After deletion: should have 0 children
  return true; // Return verification result
}

}  // namespace cascade_delete_demo
