```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  JoinAnalysis analysis;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // Return empty analysis if connection fails
    return analysis;
  }
  auto conn = conn_result.value();

  // Create temporary tables
  auto create_dept_sql = R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS Department (
      department_id INTEGER PRIMARY KEY,
      department_name TEXT NOT NULL,
      location TEXT
    )
  )";

  auto create_emp_sql = R"(
    CREATE TEMPORARY TABLE IF NOT EXISTS Employee (
      employee_id INTEGER PRIMARY KEY,
      department_id INTEGER,
      first_name TEXT NOT NULL,
      last_name TEXT NOT NULL,
      salary REAL NOT NULL,
      FOREIGN KEY (department_id) REFERENCES Department(department_id)
    )
  )";

  auto create_result = conn->execute(create_dept_sql)
    .and_then([&](auto) { return conn->execute(create_emp_sql); });

  if (!create_result) {
    return analysis;
  }

  // Insert department data
  for (const auto& dept : depts) {
    auto insert_sql = "INSERT INTO Department (department_id, department_name, location) VALUES (" +
                      std::to_string(dept.department_id) + ", '" + dept.department_name + "', '" + dept.location + "')";
    conn->execute(insert_sql);
  }

  // Insert employee data
  for (const auto& emp : emps) {
    auto insert_sql = "INSERT INTO Employee (employee_id, department_id, first_name, last_name, salary) VALUES (" +
                      std::to_string(emp.employee_id) + ", " + 
                      (emp.department_id ? std::to_string(emp.department_id) : "NULL") + ", '" +
                      emp.first_name + "', '" + emp.last_name + "', " + std::to_string(emp.salary) + ")";
    conn->execute(insert_sql);
  }

  // Perform INNER JOIN
  auto inner_join_query = select_from<Department>("department_name"_c, "first_name"_c, "last_name"_c, "salary"_c)
    .inner_join<Employee>("department_id"_c == "department_id"_c);

  auto inner_result = inner_join_query(conn);
  if (inner_result) {
    for (const auto& row : inner_result.value()) {
      JoinResult result;
      result.department_name = row.values().template get<0>();
      result.first_name = row.values().template get<1>();
      result.last_name = row.values().template get<2>();
      result.salary = row.values().template get<3>();
      analysis.inner_join_results.push_back(result);
    }
  }

  // Perform LEFT JOIN
  auto left_join_query = select_from<Employee>("department_name"_c, "first_name"_c, "last_name"_c, "salary"_c)
    .left_join<Department>("department_id"_c == "department_id"_c);

  auto left_result = left_join_query(conn);
  if (left_result) {
    for (const auto& row : left_result.value()) {
      JoinResult result;
      result.department_name = row.values().template get<0>();
      result.first_name = row.values().template get<1>();
      result.last_name = row.values().template get<2>();
      result.salary = row.values().template get<3>();
      analysis.left_join_results.push_back(result);
    }
  }

  // Perform RIGHT JOIN (emulated using LEFT JOIN with tables swapped)
  auto right_join_query = select_from<Department>("department_name"_c, "first_name"_c, "last_name"_c, "salary"_c)
    .left_join<Employee>("department_id"_c == "department_id"_c);

  auto right_result = right_join_query(conn);
  if (right_result) {
    for (const auto& row : right_result.value()) {
      JoinResult result;
      result.department_name = row.values().template get<0>();
      result.first_name = row.values().template get<1>();
      result.last_name = row.values().template get<2>();
      result.salary = row.values().template get<3>();
      analysis.right_join_results.push_back(result);
    }
  }

  // Perform FULL JOIN (emulated using UNION of LEFT and RIGHT joins)
  auto full_join_sql = R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Employee e
    LEFT JOIN Department d ON e.department_id = d.department_id
    UNION
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Department d
    LEFT JOIN Employee e ON d.department_id = e.department_id
  )";

  auto full_result = conn->read<rfl::NamedTuple<rfl::Field<"department_name", std::optional<std::string>>,
                                               rfl::Field<"first_name", std::optional<std::string>>,
                                               rfl::Field<"last_name", std::optional<std::string>>,
                                               rfl::Field<"salary", std::optional<double>>>>(full_join_sql);

  if (full_result) {
    for (const auto& row : full_result.value()) {
      JoinResult result;
      result.department_name = row.values().template get<0>();
      result.first_name = row.values().template get<1>();
      result.last_name = row.values().template get<2>();
      result.salary = row.values().template get<3>();
      analysis.full_join_results.push_back(result);
    }
  }

  return analysis;
}

}  // namespace analyze_department_employees
```

Key aspects of this implementation:

1. **Database Connection**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the SQLite database.

2. **Temporary Tables**: Creates temporary tables for Department and Employee with the specified schema.

3. **Data Insertion**: Inserts the provided department and employee data into the temporary tables.

4. **Join Operations**:
   - **INNER JOIN**: Uses `select_from<Department>().inner_join<Employee>()`
   - **LEFT JOIN**: Uses `select_from<Employee>().left_join<Department>()`
   - **RIGHT JOIN**: Emulated using a LEFT JOIN with tables swapped (since SQLite doesn't natively support RIGHT JOIN)
   - **FULL JOIN**: Emulated using a UNION of LEFT JOIN and RIGHT JOIN queries

5. **Result Collection**: For each join type, collects the results into the appropriate vector in the `JoinAnalysis` structure.

6. **Error Handling**: Gracefully handles connection and query errors by returning empty results.

The implementation follows the SQL reference queries provided and uses the `sqlgen` library's DSL for type-safe SQL query construction while handling the optional nature of join results through `std::optional` fields.

