#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace create_view_order_summary {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: This function demonstrates creating a view.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database
    auto conn = sqlite::connect("test_db.sqlite").value();

    // Create the view using create_or_replace_view_as
    auto create_view_result = 
        create_or_replace_view_as<OrderSummary>(
            select_from<Order>("order_id"_c, "customer"_c)
                .join<OrderItem>("order_id"_c == "order_id"_c)
                .group_by("order_id"_c, "customer"_c)
                .select("order_id"_c, "customer"_c, 
                        sum("unit_price"_c * "quantity"_c).as("total"))
        )(conn);

    if (!create_view_result) {
        throw std::runtime_error("Failed to create view: " + 
                               create_view_result.error().what());
    }

    // Read from the view to verify data
    auto read_result = read<std::vector<OrderSummary>>(conn);

    if (!read_result) {
        throw std::runtime_error("Failed to read from view: " + 
                               read_result.error().what());
    }

    return std::move(read_result.value());
}

}  // namespace create_view_order_summary
