Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <sqlgen/operations.hpp>
#include <sqlgen/aggregations.hpp>
#include <sqlgen/as.hpp>
#include <sqlgen/group_by.hpp>
#include <sqlgen/order_by.hpp>

namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // Return empty vector if connection fails
    return {};
  }

  auto conn = *conn_result;

  // Build the query to analyze sales by weekday
  // Extract weekday from sale_time and aggregate total quantity per weekday
  auto query = sqlgen::select_from<Sales>(
      sqlgen::weekday(Sales::sale_time) | sqlgen::as<"weekday">,
      sqlgen::sum(Sales::quantity) | sqlgen::as<"total_quantity">
    )
    | sqlgen::group_by(sqlgen::weekday(Sales::sale_time))
    | sqlgen::order_by(sqlgen::weekday(Sales::sale_time))
    | sqlgen::to<std::vector<WeekdayStats>>;

  // Execute the query and return results
  auto result = query(conn);
  if (result) {
    return std::move(*result);
  } else {
    // Return empty vector if query fails
    return {};
  }
}

}  // namespace weekday_sales_analysis
