Looking at the code structure and the requirements, I need to implement the `group_by_with_aggregations` function using the `sqlgen` library. The function should connect to an SQLite database, group posts by user, and compute aggregations (count and average content length).

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }

  auto conn = *conn_result;

  // Use sqlgen to perform the query with group by and aggregations
  auto result = sqlgen::select_from<User>(
    "user_id"_c,
    "name"_c,
    sqlgen::count().as<"post_count">,
    sqlgen::avg("content"_c).as<"avg_length">
  )
  .left_join<Post>("user_id"_c == "user_id"_c)
  .group_by("user_id"_c, "name"_c)
  .to<std::vector<Stats>>(conn);

  if (!result) {
    throw std::runtime_error("Query failed: " + result.error().what());
  }

  return *result;
}

}  // namespace group_by_with_aggregations
```

